CREATE TABLE IF NOT EXISTS series (id SERIAL PRIMARY KEY, nome VARCHAR(1) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS etapas (id SERIAL PRIMARY KEY, numero INTEGER UNIQUE NOT NULL, nome TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pilotos (id SERIAL PRIMARY KEY, nome TEXT NOT NULL, serie_id INTEGER NOT NULL REFERENCES series(id), patrocinador TEXT, etapa_patrocinio INTEGER REFERENCES etapas(numero), ativo BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(nome, serie_id));
CREATE TABLE IF NOT EXISTS resultados (id SERIAL PRIMARY KEY, piloto_id INTEGER NOT NULL REFERENCES pilotos(id) ON DELETE CASCADE, etapa_id INTEGER NOT NULL REFERENCES etapas(id), posicao INTEGER NOT NULL, pontos NUMERIC(8,2) NOT NULL DEFAULT 0, pole BOOLEAN NOT NULL DEFAULT FALSE, vmr BOOLEAN NOT NULL DEFAULT FALSE, etapa_patrocinio BOOLEAN NOT NULL DEFAULT FALSE, penalidade NUMERIC(8,2) NOT NULL DEFAULT 0, UNIQUE(piloto_id, etapa_id));
CREATE TABLE IF NOT EXISTS regras (chave TEXT PRIMARY KEY, valor JSONB NOT NULL);
